    private void verifyPendingPayment(){
        String paymentId=getPreferences(MODE_PRIVATE).getString("pendingPayment",null);if(paymentId==null||checkingPayment||user==null)return;checkingPayment=true;
        request("payments/"+paymentId,null,json->{checkingPayment=false;JSONObject status=new JSONObject(json);String value=status.optString("status");
            if("paid".equals(value)){getPreferences(MODE_PRIVATE).edit().remove("pendingPayment").apply();saveCart(new JSONArray());message(tr("Payment confirmed. Your order is placed.","تم تأكيد الدفع وإرسال طلبك."));ordersPage();}
            else if("failed".equals(value)){getPreferences(MODE_PRIVATE).edit().remove("pendingPayment").apply();message(tr("Payment was not completed. Your cart is still saved.","لم يكتمل الدفع، وسلتك ما زالت محفوظة."));checkoutPage();}
        });
        new android.os.Handler(getMainLooper()).postDelayed(()->checkingPayment=false,12000);
    }
