    private int cartQuantity(){int count=0;JSONArray rows=readCart();for(int i=0;i<rows.length();i++)count+=rows.optJSONObject(i).optInt("quantity",0);return count;}
    private void updateCartBadge(){if(cartBadge!=null){int count=cartQuantity();cartBadge.setText(count>99?"99+":String.valueOf(count));cartBadge.setVisibility(count==0?View.GONE:View.VISIBLE);}}
    private void addToCart(JSONObject product){try{if(product.optInt("stock")<1){message(tr("This product is sold out","نفدت كمية هذا المنتج"));return;}JSONArray rows=readCart();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.getJSONObject("product").getInt("id")==product.getInt("id")){if(row.optInt("quantity")>=Math.min(50,product.optInt("stock"))){message(tr("You have reached the available quantity","وصلت للكمية المتوفرة"));return;}row.put("quantity",row.optInt("quantity")+1);track("add_to_cart",product);saveCart(rows);message(tr("Added to your cart","أُضيف المنتج إلى السلة"));return;}}rows.put(new JSONObject().put("product",product).put("quantity",1));track("add_to_cart",product);saveCart(rows);message(tr("Added to your cart","أُضيف المنتج إلى السلة"));}catch(Exception e){message(e.getMessage());}}
    private void changeCartQuantity(int productId,int delta){JSONArray rows=readCart(),updated=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;JSONObject product=row.optJSONObject("product");if(product==null||product.optInt("id")!=productId){updated.put(row);continue;}int quantity=row.optInt("quantity")+delta;if(quantity>Math.min(50,product.optInt("stock"))){message(tr("You have reached the available quantity","وصلت للكمية المتوفرة"));updated.put(row);continue;}if(quantity>0){try{row.put("quantity",quantity);updated.put(row);}catch(Exception ignored){}}}saveCart(updated);cartPage();}

    private void message(String s) { Toast.makeText(this,s,Toast.LENGTH_LONG).show(); }
    private String friendlyError(String error){
        if(!arabic)return error;
        if(error==null)return "تعذر إكمال الطلب. حاول مرة أخرى.";
        switch(error){
            case "Choose an available future time after preparation":return "اختر موعداً مستقبلياً ضمن جدول الأسرة وبعد وقت التجهيز.";
            case "Not enough stock":return "الكمية المطلوبة أكبر من المخزون المتاح.";
            case "Invalid order":return "تحقق من الكمية ومعلومات الطلب.";
            case "Invalid schedule":case "Invalid working hours":return "تحقق من أوقات العمل: البداية قبل النهاية بصيغة 16:00 مثلاً.";
            case "Invalid exception":return "تحقق من تاريخ الاستثناء وساعات التوفر.";
            case "Incorrect email or password":return "البريد الإلكتروني أو كلمة المرور غير صحيحة.";
            case "Please sign in":return "سجّل الدخول لإكمال هذه الخطوة.";
            case "Access denied":return "هذه الخطوة غير متاحة لنوع حسابك.";
            case "Not found":return "الخيار غير متاح. الحسابات التجريبية تتطلب تشغيل وضع التجربة.";
            case "Enter a valid family location and choose whether you have a driver":return "حدد موقع الأسرة وعنوانها واختر هل لديها سائق.";
            case "Family delivery requires a family driver and delivery address":return "التوصيل يتطلب سائقًا لدى الأسرة وعنوانًا للعميل.";
            case "Enter a rejection reason":return "اكتب سبب الرفض.";
            case "A license application is required before approval":return "يجب إرفاق الرخصة قبل الموافقة.";
            case "Enter family contact details and attach a valid PDF, PNG or JPEG license (up to 3 MB)":return "تحقق من بيانات الأسرة وتاريخ صلاحية الرخصة، وأرفق PDF أو صورة حتى 3 ميجابايت.";
            case "Your family account is awaiting approval":return "حساب الأسرة بانتظار اعتماد المسؤول.";
            case "Ordering currently requires local demo mode; payments are simulated":return "الطلبات متاحة حالياً في وضع التجربة فقط، بدون دفع فعلي.";
            default:return error;
        }
    }
    private String readText(java.io.InputStream stream) throws java.io.IOException {
        java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int count;
        while((count=stream.read(buffer))!=-1)bytes.write(buffer,0,count);
        return bytes.toString("UTF-8");
    }
    private void request(String path,JSONObject body,Result done) {
        final int version=screenVersion;
        worker.execute(()->{HttpURLConnection connection=null;try{
            URI uri=URI.create(base+"/api/"+path);connection=(HttpURLConnection)uri.toURL().openConnection();connection.setConnectTimeout(8000);connection.setReadTimeout(8000);
            connection.setRequestProperty("X-Visitor-ID",visitorId);
            for(var entry:cookies.get(uri,java.util.Collections.emptyMap()).entrySet())connection.setRequestProperty(entry.getKey(),String.join("; ",entry.getValue()));
            if(body!=null){connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");try(var output=connection.getOutputStream()){output.write(body.toString().getBytes(StandardCharsets.UTF_8));}}
            int status=connection.getResponseCode();cookies.put(uri,connection.getHeaderFields());
            var stream=status<400?connection.getInputStream():connection.getErrorStream();String json;try(stream){json=stream==null?"{}":readText(stream);}
            if(status>=400)throw new Exception(new JSONObject(json).optString("error","Request failed"));
            runOnUiThread(()->{if(isDestroyed()||version!=screenVersion)return;try{done.accept(json);}catch(Exception e){message(e.getMessage());}});
        }catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&version==screenVersion)message(friendlyError(e.getMessage()));});}finally{if(connection!=null)connection.disconnect();}});
    }
