            FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(dp(54),dp(54),android.view.Gravity.TOP|android.view.Gravity.END);lp.setMargins(dp(6),dp(6),dp(6),0);image.addView(logo,lp);
            row.addView(image,new LinearLayout.LayoutParams(dp(106),dp(116)));LinearLayout info=column();info.setPadding(dp(12),0,dp(4),0);
