            info.addView(text(distanceLabel(f),12));JSONObject pin=f.optJSONObject("location");info.addView(text(pin==null?tr("Delivery option not set","طريقة الاستلام غير محددة"):pin.optInt("has_driver")==1?tr("Pickup · family delivery","استلام · توصيل الأسرة"):tr("Pickup only","استلام فقط"),12));
