    private int demoNumber(String key,String prefix){try{return key.startsWith(prefix)?Integer.parseInt(key.substring(prefix.length())):0;}catch(Exception e){return 0;}}
    private String productImageName(JSONObject p){String key=p.optString("demo_key");switch(key){case "product-1":return "food_jareesh_najdi";case "product-31":return "food_jareesh_white";case "product-32":return "food_jareesh_red";case "product-33":return "food_qursan";case "product-34":return "food_kabsa";case "product-35":return "food_saleeg";case "product-36":return "food_kleija";default:return key.replace('-','_');}}
    private ImageView assetImage(String name,String description,boolean crop){ImageView image=new ImageView(this);image.setContentDescription(description);image.setScaleType(crop?ImageView.ScaleType.CENTER_CROP:ImageView.ScaleType.FIT_CENTER);int resource=getResources().getIdentifier(name,"drawable",getPackageName());if(resource!=0)image.setImageResource(resource);else{image.setImageResource(android.R.drawable.ic_menu_gallery);image.setScaleType(ImageView.ScaleType.CENTER_INSIDE);}return image;}
    private void renderCards(JSONArray visible,LinearLayout target,boolean recommendation) {
        target.removeAllViews();int found=0;
        try{for(int i=0;i<visible.length();i++){JSONObject p=visible.getJSONObject(i);found++;
        LinearLayout card=column();card.setPadding(dp(16),dp(14),dp(16),dp(16));card.setBackground(background(Color.WHITE,22));card.setElevation(dp(2));
        ImageView art=assetImage(productImageName(p),p.optString("name"),true);art.setBackground(background(Color.rgb(246,240,230),16));art.setClipToOutline(true);card.addView(art,new LinearLayout.LayoutParams(-1,dp(185)));
        if(p.optString("demo_key").startsWith("product-")){TextView caption=text(tr("Illustrative demo image","صورة توضيحية للتجربة"),11);caption.setTextColor(muted);card.addView(caption);}
        TextView family=text(p.getString("family")+" · "+p.getString("region"),12);family.setTextColor(muted);card.addView(family);card.addView(text(p.getString("name"),22));
        LinearLayout priceRow=new LinearLayout(this);priceRow.setGravity(android.view.Gravity.CENTER_VERTICAL);priceRow.addView(text(String.format(java.util.Locale.US,"%.2f ",p.getInt("price")/100.0)+tr("SAR","ر.س"),20),new LinearLayout.LayoutParams(0,-2,1));TextView stock=text(p.getInt("stock")>0?tr("Available","متوفر"):tr("Sold out","نفدت الكمية"),12);stock.setTextColor(muted);priceRow.addView(stock);card.addView(priceRow);
        LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button explore=button(tr("Details","التفاصيل"),()->{if(recommendation)track("recommendation_click",p);details(p);});Button add=button(tr("Add to cart","أضف للسلة"),()->addToCart(p));LinearLayout.LayoutParams actionParams=new LinearLayout.LayoutParams(0,-2,1);actionParams.setMargins(dp(3),0,dp(3),0);actions.addView(explore,actionParams);actions.addView(add,new LinearLayout.LayoutParams(0,-2,1));card.addView(actions);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(recommendation?dp(260):-1,-2);params.bottomMargin=dp(18);if(recommendation)params.setMarginEnd(dp(12));target.addView(card,params);}if(found==0){target.addView(text(tr("No matching results","لا توجد نتائج مطابقة"),22));}}catch(Exception e){message(e.getMessage());}
    }
