    private String[] dayNames(){return arabic?new String[]{"الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"}:new String[]{"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};}
    private void manageApprovals(){screenVersion++;content.removeAllViews();content.addView(text(tr("Family applications","طلبات تسجيل الأسر"),26));request("admin/users",null,json->{JSONArray rows=new JSONArray(json);for(int i=0;i<rows.length();i++){JSONObject u=rows.getJSONObject(i);if(!u.optString("role").equals("family"))continue;content.addView(button(u.getString("name")+" · "+(u.optInt("approved")==1?tr("Approved","معتمدة"):applicationStatus(u.optString("status"))),()->reviewApplication(u.optInt("id"))));}});}
    private String applicationStatus(String status){return status.equals("rejected")?tr("Rejected","مرفوض"):status.equals("approved")?tr("Approved","معتمد"):status.equals("pending")?tr("Pending review","بانتظار المراجعة"):tr("No license attached","لم تُرفق رخصة");}
    private void reviewApplication(int id){screenVersion++;content.removeAllViews();content.addView(button(tr("Back to applications","العودة للطلبات"),this::manageApprovals));request("admin/applications/"+id,null,json->{JSONObject a=new JSONObject(json);content.addView(text(a.optString("name"),26));content.addView(text(tr("Email: ","البريد: ")+a.optString("email"),16));showFamilyLocation(a,content);
        if(a.isNull("document")){content.addView(text(tr("No license attached. Approval requires a license.","لم تُرفق رخصة. يلزم إرفاقها قبل الاعتماد."),16));return;}
        content.addView(text(tr("Phone: ","الجوال: ")+a.optString("phone"),16));content.addView(text(tr("City: ","المدينة: ")+a.optString("city"),16));content.addView(text(tr("License number: ","رقم الرخصة: ")+a.optString("license_number"),16));content.addView(text(tr("Expiry: ","تاريخ الانتهاء: ")+a.optString("license_expiry"),16));content.addView(text(applicationStatus(a.optString("status")),16));content.addView(text(a.optString("reason"),14));
        content.addView(button(tr("View attached license","عرض الرخصة المرفقة"),()->previewLicense(a)));
        content.addView(button(tr("Approve application","الموافقة على الطلب"),()->new AlertDialog.Builder(this).setTitle(tr("Approve after reviewing the license?","اعتماد الأسرة بعد مراجعة الرخصة؟")).setPositiveButton(tr("Approve","موافقة"),(d,w)->{try{request("admin/approve",new JSONObject().put("id",id).put("approved",true),result->manageApprovals());}catch(Exception e){message(e.getMessage());}}).setNegativeButton(tr("Cancel","إلغاء"),null).show()));
        content.addView(button(tr("Reject / suspend with reason","رفض / إيقاف مع ذكر السبب"),()->{LinearLayout form=column();EditText reason=input(form,tr("Reason for the family","سبب الرفض للأسرة"),false);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(tr("Rejection reason","سبب الرفض")).setView(form).setPositiveButton(tr("Submit","إرسال"),null).setNegativeButton(tr("Cancel","إلغاء"),null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{if(reason.getText().toString().trim().isEmpty()){message(tr("Enter a reason","اكتب سبب الرفض"));return;}try{request("admin/approve",new JSONObject().put("id",id).put("approved",false).put("reason",reason.getText().toString()),result->{dialog.dismiss();manageApprovals();});}catch(Exception e){message(e.getMessage());}}));dialog.show();}));
    });}
    private void previewLicense(JSONObject a){try{byte[] bytes=android.util.Base64.decode(a.getString("document"),android.util.Base64.DEFAULT);LinearLayout pages=column();
        if(a.getString("mime").equals("application/pdf")){java.io.File file=new java.io.File(getCacheDir(),"review-license.pdf");try(var out=new java.io.FileOutputStream(file)){out.write(bytes);}try(var descriptor=android.os.ParcelFileDescriptor.open(file,android.os.ParcelFileDescriptor.MODE_READ_ONLY);var renderer=new android.graphics.pdf.PdfRenderer(descriptor)){for(int i=0;i<renderer.getPageCount();i++){final int page=i;pages.addView(button(tr("View page ","عرض الصفحة ")+(i+1),()->previewPdfPage(bytes,page)));}}file.delete();}
        else{android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=Math.max(1,Math.max(options.outWidth,options.outHeight)/1600);options.inJustDecodeBounds=false;android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)throw new Exception();ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setImageBitmap(bitmap);pages.addView(image);}
        ScrollView scroll=new ScrollView(this);scroll.addView(pages);new AlertDialog.Builder(this).setTitle(tr("License attachment","مرفق الرخصة")).setView(scroll).setPositiveButton(tr("Close","إغلاق"),null).show();}catch(Exception e){message(tr("Unable to display this document","تعذر عرض هذا المرفق"));}}
    private void previewPdfPage(byte[] bytes,int index){try{java.io.File file=new java.io.File(getCacheDir(),"review-page.pdf");try(var out=new java.io.FileOutputStream(file)){out.write(bytes);}android.graphics.Bitmap bitmap;try(var descriptor=android.os.ParcelFileDescriptor.open(file,android.os.ParcelFileDescriptor.MODE_READ_ONLY);var renderer=new android.graphics.pdf.PdfRenderer(descriptor);var page=renderer.openPage(index)){int width=1200,height=Math.min(2400,Math.max(1,page.getHeight()*1200/Math.max(1,page.getWidth())));bitmap=android.graphics.Bitmap.createBitmap(width,height,android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}file.delete();ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setImageBitmap(bitmap);ScrollView scroll=new ScrollView(this);scroll.addView(image);new AlertDialog.Builder(this).setView(scroll).setPositiveButton(tr("Close","إغلاق"),null).show();}catch(Exception e){message(tr("Unable to display PDF","تعذر عرض PDF"));}}
    private void showHours(JSONObject data,LinearLayout target)throws Exception{
        target.addView(text(tr("Working hours · Saudi time","مواعيد التوفر · بتوقيت السعودية"),22));JSONArray weekly=data.getJSONArray("weekly");
        for(int day=0;day<7;day++){JSONObject row=null;for(int j=0;j<weekly.length();j++)if(weekly.getJSONObject(j).getInt("day")==day)row=weekly.getJSONObject(j);target.addView(text(dayNames()[day]+"  ·  "+(row==null?tr("Closed","إجازة"):row.getString("start")+" – "+row.getString("end")),16));}
        JSONArray exceptions=data.getJSONArray("exceptions");if(exceptions.length()>0)target.addView(text(tr("Date exceptions","استثناءات الجدول"),20));for(int i=0;i<exceptions.length();i++){JSONObject e=exceptions.getJSONObject(i);target.addView(text(e.getString("date")+" · "+(e.getBoolean("closed")?tr("Closed","إجازة"):e.getString("start")+" – "+e.getString("end")),15));}
    }
