    private String distanceLabel(JSONObject f){JSONObject pin=f.optJSONObject("location");if(pin==null)return tr("Location not set","الموقع غير محدد");boolean demo=pin.optInt("synthetic")==1;String prefix=demo?tr("Demo pin · ","موقع تجريبي · "):"";if(customerLocation==null)return prefix+tr("Set your location for distance","حدد موقعك لمعرفة المسافة");double distance=familyDistance(f);if(demo&&distance<0.5)return prefix+tr("under 1 km · approximate city location","أقل من 1 كم · موقع تقريبي داخل المدينة");if(distance<0.05)return prefix+tr("under 0.1 km · approximate direct distance","أقل من 0.1 كم · مسافة مباشرة تقريبية");return prefix+String.format(java.util.Locale.US,"%.1f",distance)+tr(" km · approximate direct distance"," كم · مسافة مباشرة تقريبية");}
