    private void locate(java.util.function.Consumer<android.location.Location> done){pendingLocation=done;if(checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},510);return;}readLocation();}
    private void readLocation(){try{android.location.LocationManager manager=(android.location.LocationManager)getSystemService(LOCATION_SERVICE);if(activeLocationListener!=null){manager.removeUpdates(activeLocationListener);activeLocationListener=null;}android.location.Location recent=null;for(String provider:manager.getProviders(true)){try{android.location.Location found=manager.getLastKnownLocation(provider);if(found!=null&&(recent==null||found.getTime()>recent.getTime()))recent=found;}catch(SecurityException ignored){}}if(recent!=null&&System.currentTimeMillis()-recent.getTime()<300000){deliverLocation(recent);return;}
        final int version=screenVersion;activeLocationListener=new android.location.LocationListener(){public void onLocationChanged(android.location.Location location){manager.removeUpdates(this);if(activeLocationListener==this)activeLocationListener=null;if(version==screenVersion)deliverLocation(location);}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}public void onStatusChanged(String p,int status,Bundle extras){}};boolean requested=false;for(String provider:new String[]{android.location.LocationManager.NETWORK_PROVIDER,android.location.LocationManager.GPS_PROVIDER}){if(manager.isProviderEnabled(provider)){try{manager.requestLocationUpdates(provider,0,0,activeLocationListener);requested=true;}catch(SecurityException ignored){}}}if(!requested){activeLocationListener=null;message(tr("Enable location services and try again","فعّل خدمة الموقع وحاول مرة أخرى"));return;}message(tr("Getting your location…","جار تحديد موقعك…"));final android.location.LocationListener listener=activeLocationListener;new android.os.Handler(getMainLooper()).postDelayed(()->{if(activeLocationListener==listener){manager.removeUpdates(listener);activeLocationListener=null;pendingLocation=null;if(version==screenVersion)message(tr("Location unavailable. Try again outdoors.","تعذر تحديد الموقع. حاول مرة أخرى في مكان مفتوح."));}},20000);
    }catch(Exception e){message(tr("Unable to get location","تعذر تحديد الموقع"));}}
    private void deliverLocation(android.location.Location location){java.util.function.Consumer<android.location.Location> done=pendingLocation;pendingLocation=null;if(done!=null)done.accept(location);}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==510){if(checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)==android.content.pm.PackageManager.PERMISSION_GRANTED||checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==android.content.pm.PackageManager.PERMISSION_GRANTED)readLocation();else{pendingLocation=null;message(tr("You can browse without distance or nearest sorting","تقدر تتصفح بدون المسافة وترتيب الأقرب"));}}}
    private void locationForm(JSONObject existing,java.util.function.Consumer<JSONObject> done){LinearLayout form=column();form.addView(text(tr("Your pickup location is visible to customers. Select it while at the family location.","موقع الاستلام سيظهر للعملاء. حدده وأنت في موقع الأسرة."),14));EditText address=input(form,tr("Pickup address / neighborhood","عنوان الاستلام / الحي"),false),lat=input(form,tr("Latitude","خط العرض"),false),lon=input(form,tr("Longitude","خط الطول"),false);lat.setVisibility(View.GONE);lon.setVisibility(View.GONE);TextView locationStatus=text(existing==null?tr("Detecting your location automatically…","جار تحديد موقعك تلقائيًا…"):tr("Saved pickup location","موقع الاستلام المحفوظ"),15);form.addView(locationStatus);
        Spinner driver=new Spinner(this);driver.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{tr("Do you have a delivery driver?","هل عندك سائق للتوصيل؟"),tr("No · pickup only","لا · استلام فقط"),tr("Yes · family delivery available","نعم · توصيل بواسطة الأسرة")}));form.addView(driver);if(existing!=null){address.setText(existing.optString("address"));lat.setText(String.valueOf(existing.optDouble("latitude")));lon.setText(String.valueOf(existing.optDouble("longitude")));driver.setSelection(existing.optInt("has_driver")==1?2:1);}
        java.util.function.Consumer<android.location.Location> fillLocation=location->{lat.setText(String.valueOf(location.getLatitude()));lon.setText(String.valueOf(location.getLongitude()));locationStatus.setText(tr("Current location detected · confirm before saving","تم تحديد موقعك الحالي · تأكد منه قبل الحفظ"));};
        form.addView(button(tr("Detect location again","إعادة تحديد الموقع"),()->locate(fillLocation)));
        form.addView(button(tr("Check detected location on map","تأكد من الموقع على الخريطة"),()->{try{double latitude=Double.parseDouble(lat.getText().toString()),longitude=Double.parseDouble(lon.getText().toString());startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse("https://www.google.com/maps/search/?api=1&query="+latitude+","+longitude)));}catch(Exception e){message(tr("Wait for location detection","انتظر حتى يتم تحديد الموقع"));}}));
        form.addView(text(tr("Be at the family pickup location. Your location is saved only when you confirm.","لازم تكون في موقع استلام الأسرة. الموقع يُحفظ بعد تأكيدك فقط."),13));ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(tr("Family location & delivery","موقع الأسرة والتوصيل")).setView(scroll).setPositiveButton(tr("Save","حفظ"),null).setNegativeButton(tr("Cancel","إلغاء"),null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{double latitude=Double.parseDouble(lat.getText().toString()),longitude=Double.parseDouble(lon.getText().toString());if(!Double.isFinite(latitude)||!Double.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180||address.getText().toString().trim().isEmpty()||driver.getSelectedItemPosition()==0)throw new Exception();done.accept(new JSONObject().put("latitude",latitude).put("longitude",longitude).put("address",address.getText().toString().trim()).put("hasDriver",driver.getSelectedItemPosition()==2));dialog.dismiss();}catch(Exception e){message(tr("Enter a valid location, address, and driver option","حدد موقعًا صحيحًا وعنوان الاستلام واختر هل يوجد سائق"));}}));dialog.setOnDismissListener(d->{if(activeLocationListener!=null){((android.location.LocationManager)getSystemService(LOCATION_SERVICE)).removeUpdates(activeLocationListener);activeLocationListener=null;}pendingLocation=null;});dialog.show();locate(fillLocation);}
    private void licenseForm(java.util.function.Consumer<JSONObject> done){
        licenseFile=null;LinearLayout form=column();form.addView(text(tr("Required selling license · PDF / PNG / JPEG · up to 3 MB","رخصة البيع مطلوبة · PDF أو صورة · حتى 3 ميجابايت"),14));
        EditText phone=input(form,tr("Mobile number","رقم الجوال"),false);phone.setInputType(3);EditText city=input(form,tr("City","المدينة"),false);EditText number=input(form,tr("License number","رقم الرخصة"),false);EditText expiry=input(form,tr("License expiry date","تاريخ انتهاء الرخصة"),false);expiry.setFocusable(false);expiry.setOnClickListener(v->{java.util.Calendar c=java.util.Calendar.getInstance();new android.app.DatePickerDialog(this,(view,y,m,d)->expiry.setText(String.format(java.util.Locale.US,"%04d-%02d-%02d",y,m+1,d)),c.get(1),c.get(2),c.get(5)).show();});
        attachmentLabel=text(tr("No file selected","لم يتم اختيار ملف"),14);form.addView(attachmentLabel);form.addView(button(tr("Attach license","إرفاق الرخصة"),()->{android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(android.content.Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(android.content.Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/png","image/jpeg"});startActivityForResult(intent,410);}));
        ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(tr("Family registration details","بيانات تسجيل الأسرة" )).setView(scroll).setPositiveButton(tr("Submit for review","إرسال للمراجعة"),null).setNegativeButton(tr("Cancel","إلغاء"),null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{if(licenseFile==null||phone.getText().toString().trim().isEmpty()||city.getText().toString().trim().isEmpty()||number.getText().toString().trim().isEmpty()||expiry.getText().length()==0){message(tr("Complete details and attach your license","أكمل البيانات وأرفق الرخصة"));return;}try{JSONObject a=new JSONObject(licenseFile.toString()).put("phone",phone.getText().toString().trim()).put("city",city.getText().toString().trim()).put("licenseNumber",number.getText().toString().trim()).put("licenseExpiry",expiry.getText().toString());done.accept(a);dialog.dismiss();}catch(Exception e){message(e.getMessage());}}));dialog.show();
    }
    @Override protected void onActivityResult(int requestCode,int resultCode,android.content.Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=410||resultCode!=RESULT_OK||data==null)return;try{android.net.Uri uri=data.getData();String mime=getContentResolver().getType(uri),name="license";try(var cursor=getContentResolver().query(uri,null,null,null,null)){if(cursor!=null&&cursor.moveToFirst()){int col=cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);if(col>=0)name=cursor.getString(col);}}byte[] bytes;try(var stream=getContentResolver().openInputStream(uri)){java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=stream.read(buffer))!=-1){output.write(buffer,0,count);if(output.size()>3*1024*1024)throw new Exception(tr("Maximum file size is 3 MB","حجم الملف يجب ألا يتجاوز 3 ميجابايت"));}bytes=output.toByteArray();}if(bytes.length>3*1024*1024)throw new Exception(tr("Maximum file size is 3 MB","حجم الملف يجب ألا يتجاوز 3 ميجابايت"));licenseFile=new JSONObject().put("filename",name).put("mime",mime).put("document",android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP));attachmentLabel.setText(name);}catch(Exception e){licenseFile=null;message(e.getMessage());}}
    private void auth(boolean register) {
        LinearLayout form=column();EditText name=register?input(form,tr("Name","الاسم"),false):null;EditText email=input(form,tr("Email","البريد الإلكتروني"),false);email.setInputType(33);EditText password=input(form,tr("Password (10+ characters)","كلمة المرور (10 أحرف على الأقل)"),true);
        Spinner role=new Spinner(this);if(register){role.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{tr("Customer","عميل"),tr("Productive family","أسرة منتجة")}));form.addView(role);}
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(register?tr("Join Osrah","انضم إلى أسرة"):tr("Sign in","تسجيل الدخول")).setView(form).setPositiveButton(tr("Continue","متابعة"),null).setNegativeButton(tr("Cancel","إلغاء"),null).create();
        dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{JSONObject body=new JSONObject().put("email",email.getText().toString().trim()).put("password",password.getText().toString());if(register)body.put("name",name.getText().toString()).put("role",role.getSelectedItemPosition()==0?"customer":"family");
        if(register&&body.optString("role").equals("family")){licenseForm(application->locationForm(null,location->{try{body.put("application",application).put("location",location);request("register",body,json->{dialog.dismiss();request("login",new JSONObject().put("email",body.optString("email")).put("password",body.optString("password")),result->{user=new JSONObject(result);account();});});}catch(Exception e){message(e.getMessage());}}));return;}
        request(register?"register":"login",body,json->{dialog.dismiss();if(register)message(tr("Account created. Please sign in.","تم إنشاء الحساب. سجّل دخولك."));account();});}catch(Exception e){message(e.getMessage());}}));dialog.show();
    }
    private void settings() {
        selectNav(2);
        screenVersion++;content.removeAllViews();content.addView(text(tr("Settings","الإعدادات"),28));content.addView(text(tr("Make Osrah feel like home.","أسرة بالطريقة اللي تناسبك."),16));
        LinearLayout preferences=column();preferences.setBackground(background(Color.WHITE,20));preferences.addView(text(tr("App language","لغة التطبيق"),20));preferences.addView(text(arabic?"العربية":"English",16));
        preferences.addView(button(tr("Change language","تغيير اللغة"),()->new AlertDialog.Builder(this).setTitle(tr("App language","لغة التطبيق")).setSingleChoiceItems(new String[]{"العربية","English"},arabic?0:1,(dialog,which)->{arabic=which==0;getPreferences(MODE_PRIVATE).edit().putBoolean("arabic",arabic).apply();dialog.dismiss();shell();settings();}).setNegativeButton(tr("Cancel","إلغاء"),null).show()));content.addView(preferences);
        content.addView(text(tr("Osrah · Supporting local families","أسرة · ندعم الأسر المنتجة"),14));
        if(BuildConfig.DEBUG)content.addView(button(tr("Developer connection settings","إعدادات اتصال المطوّر"),this::connectionSettings));
    }
    private void connectionSettings() {LinearLayout form=column();EditText endpoint=input(form,"API URL",false);endpoint.setText(base);new AlertDialog.Builder(this).setTitle(tr("Server settings","إعدادات الخادم")).setView(form).setPositiveButton(tr("Save","حفظ"),(d,w)->{String next=endpoint.getText().toString().trim().replaceAll("/+$","");try{URI uri=URI.create(next);if(!java.util.Arrays.asList("http","https").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new Exception();base=next;cookies.getCookieStore().removeAll();getPreferences(MODE_PRIVATE).edit().putString("api",base).apply();marketplace();}catch(Exception e){message(tr("Enter a valid server URL","أدخل عنوان خادم صحيحاً"));}}).setNegativeButton(tr("Cancel","إلغاء"),null).show();}
